// Cria o "banco de dados" simulado da clínica: três listas vazias.
export function criarBanco() {
  return { medicos: [], pacientes: [], consultas: [] };
}

// Transação simulada: trabalha numa cópia (rascunho) e só devolve o
// resultado se TODAS as operações funcionarem. Se qualquer uma lançar
// erro, o erro sobe e o estado original nem é tocado (rollback).
export function rodarTransacao(estado, operacoes) {
  if (!Array.isArray(operacoes)) {
    throw new Error('operacoes precisa ser uma lista');
  }
  const rascunho = JSON.parse(JSON.stringify(estado));
  for (const operacao of operacoes) {
    operacao(rascunho);
  }
  return rascunho;
}

// Validação comum: o cadastro precisa de nome (texto não vazio).
function validarNome(registro, tipo) {
  if (!registro || typeof registro.nome !== 'string' || registro.nome.trim() === '') {
    throw new Error(`${tipo} precisa ter nome`);
  }
}

export function cadastrarMedico(banco, medico) {
  validarNome(medico, 'medico');
  const comId = { id: banco.medicos.length + 1, ...medico };
  banco.medicos.push(comId);
  return comId;
}

export function cadastrarPaciente(banco, paciente) {
  validarNome(paciente, 'paciente');
  const comId = { id: banco.pacientes.length + 1, ...paciente };
  banco.pacientes.push(comId);
  return comId;
}

// Agenda uma consulta validando TUDO antes de tocar no banco: se
// qualquer checagem falhar, nada é adicionado (tudo ou nada).
export function agendarConsulta(banco, consulta) {
  if (!consulta || typeof consulta.medicoId !== 'number' || typeof consulta.pacienteId !== 'number') {
    throw new Error('consulta precisa de medicoId e pacienteId numéricos');
  }
  if (typeof consulta.dia !== 'string' || typeof consulta.hora !== 'string') {
    throw new Error('consulta precisa de dia e hora em texto');
  }
  const medico = banco.medicos.find((m) => m.id === consulta.medicoId);
  if (!medico) {
    throw new Error(`médico ${consulta.medicoId} não existe`);
  }
  const paciente = banco.pacientes.find((p) => p.id === consulta.pacienteId);
  if (!paciente) {
    throw new Error(`paciente ${consulta.pacienteId} não existe`);
  }
  const comId = { id: banco.consultas.length + 1, ...consulta };
  banco.consultas.push(comId);
  return comId;
}

