// Acha o nome de um paciente pelo id, ou null se não existir.
function nomePaciente(banco, id) {
  const paciente = banco.pacientes.find((p) => p.id === id);
  return paciente ? paciente.nome : null;
}

// Acha o nome de um médico pelo id, ou null se não existir.
function nomeMedico(banco, id) {
  const medico = banco.medicos.find((m) => m.id === id);
  return medico ? medico.nome : null;
}

// JOIN simulado: a consulta vira um objeto com os nomes juntados.
function enriquecer(banco, consulta) {
  return {
    id: consulta.id,
    dia: consulta.dia,
    hora: consulta.hora,
    paciente: nomePaciente(banco, consulta.pacienteId),
    medico: nomeMedico(banco, consulta.medicoId),
  };
}

// WHERE + JOIN: filtra pelo dia e junta os nomes (consultasDoDia).
export function consultasDoDia(banco, dia) {
  return banco.consultas
    .filter((consulta) => consulta.dia === dia)
    .map((consulta) => enriquecer(banco, consulta));
}

// LEFT JOIN: para cada médico, as consultas dele; sem par, lista vazia.
export function medicosComConsultas(banco) {
  return banco.medicos.map((medico) => ({
    nome: medico.nome,
    especialidade: medico.especialidade,
    consultas: banco.consultas
      .filter((c) => c.medicoId === medico.id)
      .map((c) => ({
        dia: c.dia,
        hora: c.hora,
        paciente: nomePaciente(banco, c.pacienteId),
      })),
  }));
}

// WHERE duplo + JOIN: médico E dia certos, com o nome do paciente.
export function agendaDoMedico(banco, medicoId, dia) {
  return banco.consultas
    .filter((c) => c.medicoId === medicoId && c.dia === dia)
    .map((c) => ({
      hora: c.hora,
      paciente: nomePaciente(banco, c.pacienteId),
    }));
}

