// Escapa um termo digitado para usar numa busca com segurança:
// ' vira '' (como no SQL) e os coringas % e _ viram \% e \_ (literal).
export function escaparParaLike(termo) {
  if (typeof termo !== 'string') {
    throw new Error('termo precisa ser texto');
  }
  return termo
    .replaceAll("'", "''")
    .replaceAll('%', '\\%')
    .replaceAll('_', '\\_');
}

// Simula o LIKE do SQL sobre uma string.
// Regras do padrão: % = qualquer coisa, _ = um caractere, \X = X literal.
export function casaComLike(texto, padrao) {
  let regex = '';
  for (let i = 0; i < padrao.length; i++) {
    const caractere = padrao[i];
    if (caractere === '\\' && i + 1 < padrao.length) {
      // a barra indica que o PRÓXIMO caractere é literal, não coringa
      regex += escaparNaRegex(padrao[++i]);
    } else if (caractere === '%') {
      regex += '.*'; // qualquer coisa (inclusive nada)
    } else if (caractere === '_') {
      regex += '.'; // um caractere qualquer
    } else {
      regex += escaparNaRegex(caractere);
    }
  }
  return new RegExp('^' + regex + '$', 'i').test(texto);
}

// Foge dos caracteres especiais de regex (., *, ?, +, [, ], etc.)
function escaparNaRegex(caractere) {
  return caractere.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// Busca com "contém": o termo é escapado (vira texto literal) e entra
// num padrão com % nas duas pontas — o usuário nunca manda comando.
export function buscarPacientesPorNome(banco, termo) {
  const padrao = '%' + escaparParaLike(termo) + '%';
  return banco.pacientes.filter((paciente) => casaComLike(paciente.nome, padrao));
}

