import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  criarBanco,
  rodarTransacao,
  cadastrarMedico,
  cadastrarPaciente,
  agendarConsulta,
} from './lib/banco.mjs';
import {
  consultasDoDia,
  medicosComConsultas,
  agendaDoMedico,
} from './lib/consultas.mjs';
import {
  escaparParaLike,
  casaComLike,
  buscarPacientesPorNome,
} from './lib/seguranca.mjs';

// Clínica com 2 médicos, 2 pacientes e 3 consultas (usada em vários testes)
function bancoCompleto() {
  const banco = criarBanco();
  cadastrarMedico(banco, { nome: 'Dra. Carla', especialidade: 'cardiologia', email: 'carla@clinica.com' });
  cadastrarMedico(banco, { nome: 'Dr. Beto', especialidade: 'ortopedia', email: 'beto@clinica.com' });
  cadastrarPaciente(banco, { nome: 'Ana' });
  cadastrarPaciente(banco, { nome: 'Mariana' });
  agendarConsulta(banco, { medicoId: 1, pacienteId: 1, dia: '2026-08-27', hora: '10:00' });
  agendarConsulta(banco, { medicoId: 2, pacienteId: 1, dia: '2026-08-27', hora: '11:00' });
  agendarConsulta(banco, { medicoId: 2, pacienteId: 2, dia: '2026-08-28', hora: '09:00' });
  return banco;
}

test('cadastrarMedico e cadastrarPaciente devolvem com id automático', () => {
  const banco = criarBanco();
  const carla = cadastrarMedico(banco, { nome: 'Dra. Carla', especialidade: 'cardiologia', email: 'carla@clinica.com' });
  assert.deepEqual(carla, { id: 1, nome: 'Dra. Carla', especialidade: 'cardiologia', email: 'carla@clinica.com' });
  const ana = cadastrarPaciente(banco, { nome: 'Ana' });
  assert.deepEqual(ana, { id: 1, nome: 'Ana' });
  assert.equal(banco.medicos.length, 1);
  assert.equal(banco.pacientes.length, 1);
});

test('agendarConsulta valida tudo antes de adicionar (nada muda no erro)', () => {
  const banco = bancoCompleto();
  assert.throws(
    () => agendarConsulta(banco, { medicoId: 1, pacienteId: 99, dia: '2026-08-27', hora: '11:00' }),
    /paciente 99/,
  );
  assert.throws(
    () => agendarConsulta(banco, { medicoId: 99, pacienteId: 1, dia: '2026-08-27', hora: '11:00' }),
    /médico 99/,
  );
  assert.throws(
    () => agendarConsulta(banco, { medicoId: 1, pacienteId: 1, dia: 20260827, hora: '11:00' }),
    /dia/,
  );
  assert.equal(banco.consultas.length, 3); // nenhuma consulta falsa entrou
  const nova = agendarConsulta(banco, { medicoId: 1, pacienteId: 1, dia: '2026-08-29', hora: '09:00' });
  assert.deepEqual(nova, { id: 4, medicoId: 1, pacienteId: 1, dia: '2026-08-29', hora: '09:00' });
});

test('rodarTransacao comita tudo ou desfaz tudo', () => {
  const banco = criarBanco();
  const resultado = rodarTransacao(banco, [
    (rascunho) => rascunho.pacientes.push({ id: 1, nome: 'Ana' }),
    (rascunho) => rascunho.pacientes.push({ id: 2, nome: 'Beto' }),
  ]);
  assert.equal(resultado.pacientes.length, 2);
  assert.equal(banco.pacientes.length, 0); // original intocado (cópia)
  assert.throws(
    () => rodarTransacao(banco, [
      (rascunho) => rascunho.pacientes.push({ id: 1, nome: 'Ana' }),
      () => { throw new Error('deu ruim'); },
    ]),
    /deu ruim/,
  );
  assert.equal(banco.pacientes.length, 0); // nem o push que funcionou vazou
  assert.throws(() => rodarTransacao(banco, 'nada'), /lista/);
});

test('consultasDoDia e agendaDoMedico filtram e juntam os nomes', () => {
  const banco = bancoCompleto();
  const dia27 = consultasDoDia(banco, '2026-08-27');
  assert.equal(dia27.length, 2);
  assert.deepEqual(dia27[0], { id: 1, dia: '2026-08-27', hora: '10:00', paciente: 'Ana', medico: 'Dra. Carla' });
  assert.equal(dia27[1].medico, 'Dr. Beto');
  assert.deepEqual(consultasDoDia(banco, '2026-09-01'), []);
  const agendaCarla = agendaDoMedico(banco, 1, '2026-08-27');
  assert.deepEqual(agendaCarla, [{ hora: '10:00', paciente: 'Ana' }]);
  assert.deepEqual(agendaDoMedico(banco, 1, '2026-08-28'), []);
});

test('medicosComConsultas agrupa as consultas por médico (LEFT JOIN)', () => {
  const banco = bancoCompleto();
  const grupos = medicosComConsultas(banco);
  assert.equal(grupos.length, 2);
  assert.deepEqual(grupos[0], {
    nome: 'Dra. Carla',
    especialidade: 'cardiologia',
    consultas: [{ dia: '2026-08-27', hora: '10:00', paciente: 'Ana' }],
  });
  assert.deepEqual(grupos[1].consultas, [
    { dia: '2026-08-27', hora: '11:00', paciente: 'Ana' },
    { dia: '2026-08-28', hora: '09:00', paciente: 'Mariana' },
  ]);
  // médico sem consulta entra com lista vazia
  const bancoVazio = criarBanco();
  cadastrarMedico(bancoVazio, { nome: 'Dr. Sem Agenda', especialidade: 'neurologia' });
  assert.deepEqual(medicosComConsultas(bancoVazio)[0].consultas, []);
});

test('busca por nome: normal, injeção e coringas neutralizados', () => {
  const banco = criarBanco();
  cadastrarPaciente(banco, { nome: 'Ana' });
  cadastrarPaciente(banco, { nome: 'Mariana' });
  cadastrarPaciente(banco, { nome: 'Ana 100% fiel' });
  cadastrarPaciente(banco, { nome: 'Ana_Maria' });

  // busca normal, sem diferenciar maiúsculas
  assert.deepEqual(
    buscarPacientesPorNome(banco, 'ana').map((p) => p.nome),
    ['Ana', 'Mariana', 'Ana 100% fiel', 'Ana_Maria'],
  );

  // a tentativa de injeção vira texto literal: ninguém se chama assim
  assert.deepEqual(buscarPacientesPorNome(banco, "' OR '1'='1"), []);

  // o % digitado deixa de ser coringa: só acha quem tem % no nome
  assert.deepEqual(
    buscarPacientesPorNome(banco, '%').map((p) => p.nome),
    ['Ana 100% fiel'],
  );

  // o _ digitado deixa de ser coringa: só acha quem tem _ no nome
  assert.deepEqual(
    buscarPacientesPorNome(banco, '_').map((p) => p.nome),
    ['Ana_Maria'],
  );

  // escapes diretos
  assert.equal(escaparParaLike("O'Brien"), "O''Brien");
  assert.equal(escaparParaLike('100%'), '100\\%');
  assert.throws(() => escaparParaLike(42), /texto/);
  assert.equal(casaComLike('Ana Maria', '%ana%'), true);
  assert.equal(casaComLike('Beto', '%ana%'), false);
  assert.equal(casaComLike('Ana 100%', '%\\%%'), true); // \% é % literal
});
